(function () {
        const loader = document.getElementById('intro-loader');
        const bar = document.querySelector('.intro-progress-bar');
        const counter = document.querySelector('.intro-counter');
        if (!loader) return;

        document.body.classList.add('intro-active');

        let progress = 0;
        const speed = () => Math.max(2, (100 - progress) * 0.08);

        const interval = setInterval(() => {
            progress += speed();
            if (progress >= 100) {
                progress = 100;
                clearInterval(interval);
                setTimeout(finishIntro, 350);
            }
            bar.style.width = progress + '%';
            counter.textContent = Math.floor(progress) + '%';
        }, 60);

        function finishIntro() {
            loader.classList.add('done');
            document.body.classList.remove('intro-active');
            if (window.AOS) setTimeout(() => AOS.refresh(), 400);
            setTimeout(() => loader.remove(), 1200);
        }

        setTimeout(() => { if (!loader.classList.contains('done')) finishIntro(); }, 4000);
    })();

