const profileTechCanvas = document.getElementById("profileTechCanvas");
const profileTechCtx = profileTechCanvas?.getContext("2d");

let profileTechAnimationId = null;
let profileTechParticles = [];

let profileTechWidth = 0;
let profileTechHeight = 0;

const profileTechReducedMotion =
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

function resizeProfileTechCanvas() {
    if (!profileTechCanvas || !profileTechCtx) return;

    const dpr = Math.min(window.devicePixelRatio || 1, 1.5);

    profileTechWidth = window.innerWidth;
    profileTechHeight = window.innerHeight;

    profileTechCanvas.width = Math.floor(profileTechWidth * dpr);
    profileTechCanvas.height = Math.floor(profileTechHeight * dpr);

    profileTechCtx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const particleCount = Math.min(
        68,
        Math.max(
            26,
            Math.floor(
                (profileTechWidth * profileTechHeight) / 22000
            )
        )
    );

    profileTechParticles = Array.from(
        { length: particleCount },
        () => ({
            x: Math.random() * profileTechWidth,
            y: Math.random() * profileTechHeight,

            vx: (Math.random() - 0.5) * 0.35,
            vy: (Math.random() - 0.5) * 0.35,

            radius: Math.random() * 1.8 + 0.7
        })
    );
}

function animateProfileTech() {
    if (!profileTechCtx) return;

    const ctx = profileTechCtx;

    ctx.clearRect(
        0,
        0,
        profileTechWidth,
        profileTechHeight
    );

    // Move particles
    profileTechParticles.forEach(particle => {
        particle.x += particle.vx;
        particle.y += particle.vy;

        if (particle.x < 0) particle.x = profileTechWidth;
        if (particle.x > profileTechWidth) particle.x = 0;

        if (particle.y < 0) particle.y = profileTechHeight;
        if (particle.y > profileTechHeight) particle.y = 0;
    });

    // Connect nearby particles
    for (let i = 0; i < profileTechParticles.length; i++) {

        const a = profileTechParticles[i];

        for (let j = i + 1; j < profileTechParticles.length; j++) {

            const b = profileTechParticles[j];

            const dx = a.x - b.x;
            const dy = a.y - b.y;

            const distance = Math.sqrt(dx * dx + dy * dy);

            if (distance < 150) {

                const opacity = 0.20 * (1 - distance / 150);

                ctx.beginPath();

                ctx.moveTo(a.x, a.y);
                ctx.lineTo(b.x, b.y);

           ctx.strokeStyle =
    `rgba(212, 175, 55, ${opacity})`;

                ctx.lineWidth = 0.8;
                ctx.stroke();
            }
        }
    }

    // Draw glowing particles
    profileTechParticles.forEach(particle => {

        ctx.beginPath();

        ctx.arc(
            particle.x,
            particle.y,
            particle.radius,
            0,
            Math.PI * 2
        );

    ctx.fillStyle = "rgba(245, 215, 110, 0.85)";
ctx.shadowBlur = 14;
ctx.shadowColor = "#D4AF37";

        ctx.fill();

        ctx.shadowBlur = 0;
    });

    profileTechAnimationId =
        requestAnimationFrame(animateProfileTech);
}

// Start animation when opening SEE MORE
window.startProfileTech = function () {

    if (
        !profileTechCanvas ||
        !profileTechCtx ||
        profileTechReducedMotion ||
        profileTechAnimationId !== null
    ) return;

    resizeProfileTechCanvas();
    animateProfileTech();
};

// Stop animation when leaving profile
window.stopProfileTech = function () {

    if (profileTechAnimationId !== null) {

        cancelAnimationFrame(profileTechAnimationId);

        profileTechAnimationId = null;
    }
};

