/* Open/close the book with a cinematic 3D cover animation. */
function setProfileBookOpen(isOpen) {
    if (!profileBookClosed || !profileBookContainer || !profileBookShell) return;

    if (profileBookOpeningTimer) {
        clearTimeout(profileBookOpeningTimer);
        profileBookOpeningTimer = null;
    }

    if (isOpen) {
        profileBookClosed.hidden = true;
        profileBookContainer.hidden = false;

        profileBookContainer.classList.remove("is-opening", "book-reveal");
        profileBookShell.classList.remove("is-opening");
        void profileBookShell.offsetWidth;

        requestAnimationFrame(() => {
            profileBookContainer.classList.add("is-opening");
            profileBookShell.classList.add("is-opening");
        });

        profileBookToggle?.setAttribute("aria-expanded", "true");

        profileBookOpeningTimer = window.setTimeout(() => {
            profileBookOpeningTimer = null;
        }, 2050);

        window.setTimeout(() => {
            profileBookContainer.scrollIntoView({
                behavior: "smooth",
                block: "center"
            });
        }, 180);
    } else {
        profileBookContainer.classList.remove("is-opening", "book-reveal");
        profileBookShell.classList.remove("is-opening");
        if (profileBookSheet) {
            profileBookSheet.className = "profile-book-flip-sheet";
            profileBookSheet.style.display = "none";
        }
        profileBookIsAnimating = false;
        profileBookContainer.hidden = true;
        profileBookClosed.hidden = false;
        profileBookToggle?.setAttribute("aria-expanded", "false");
    }
}

profileBookToggle?.addEventListener("click", () => {
