/* Swipe left/right across the open book to turn pages on touch screens. */
let profileBookSwipeStartX = null;

profileBookShell?.addEventListener("pointerdown", (event) => {
    profileBookSwipeStartX = event.clientX;
}, { passive: true });

profileBookShell?.addEventListener("pointerup", (event) => {
    if (profileBookSwipeStartX === null || profileBookIsAnimating) return;

    const distance = event.clientX - profileBookSwipeStartX;
    profileBookSwipeStartX = null;

    if (Math.abs(distance) < 55) return;

    if (distance < 0) {
        flipProfileBook(1);
    } else {
        flipProfileBook(-1);
    }
}, { passive: true });

profileBookShell?.addEventListener("pointercancel", () => {
    profileBookSwipeStartX = null;
}, { passive: true });

/* Keyboard navigation while the book is open. */
document.addEventListener("keydown", (event) => {
    if (!profileBookContainer || profileBookContainer.hidden) return;
    if (profileBookLightbox?.classList.contains("active")) return;
    if (event.target?.matches("input, textarea, select, [contenteditable='true']")) return;

    if (event.key === "ArrowRight") {
        event.preventDefault();
        flipProfileBook(1);
    } else if (event.key === "ArrowLeft") {
        event.preventDefault();
        flipProfileBook(-1);
    }
});

/* Subtle pointer tilt on the closed book cover; disabled for touch/reduced motion. */
if (profileBookClosed && !window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    const cover = profileBookClosed.querySelector(".book-closed-cover");
    if (cover) {
        profileBookClosed.addEventListener("pointermove", (event) => {
            if (event.pointerType === "touch") return;
            const rect = profileBookClosed.getBoundingClientRect();
            const x = (event.clientX - rect.left) / rect.width - 0.5;
            const y = (event.clientY - rect.top) / rect.height - 0.5;
            cover.style.setProperty("--cover-tilt-x", `${x * 7}deg`);
            cover.style.setProperty("--cover-tilt-y", `${-y * 5}deg`);
        });
        profileBookClosed.addEventListener("pointerleave", () => {
            cover.style.setProperty("--cover-tilt-x", "0deg");
            cover.style.setProperty("--cover-tilt-y", "0deg");
        });
    }
}


