/* UPDATE BOTH PAGES AND PROGRESS */
function updateProfileBook() {

    const leftPhoto =
        activeProfileBookPhotos[activeProfileBookIndex];

    const rightPhoto =
        activeProfileBookPhotos[activeProfileBookIndex + 1];

    fillProfileBookPage(
        "Left",
        leftPhoto,
        activeProfileBookIndex + 1
    );

    fillProfileBookPage(
        "Right",
        rightPhoto,
        activeProfileBookIndex + 2
    );

    const totalSpreads = Math.ceil(
        activeProfileBookPhotos.length / 2
    );

    const currentSpread =
        Math.floor(activeProfileBookIndex / 2) + 1;

    if (profileBookSpread) {
        profileBookSpread.textContent =
            `SPREAD ${String(currentSpread).padStart(2, "0")} / ${String(totalSpreads).padStart(2, "0")}`;
    }

    if (profileBookProgress) {
        profileBookProgress.style.width =
            `${(currentSpread / totalSpreads) * 100}%`;
    }

    if (profileBookPrev) {
        profileBookPrev.disabled =
            activeProfileBookIndex === 0;
    }

    if (profileBookNext) {
        profileBookNext.disabled =
            activeProfileBookIndex + 2 >=
            activeProfileBookPhotos.length;
    }
}


/* REALISTIC NEXT / PREVIOUS PAGE TURN */
function flipProfileBook(direction) {

    if (
        profileBookIsAnimating ||
        !activeProfileBookPhotos.length ||
        !profileBookSheet
    ) return;

    const targetIndex = Math.max(
        0,
        Math.min(
            activeProfileBookPhotos.length - 1,
            activeProfileBookIndex + (direction * 2)
        )
    );

    if (targetIndex === activeProfileBookIndex) return;

    profileBookIsAnimating = true;

    const frontPhoto = direction === 1
        ? activeProfileBookPhotos[activeProfileBookIndex + 1]
            || activeProfileBookPhotos[activeProfileBookIndex]
        : activeProfileBookPhotos[activeProfileBookIndex];

    const backPhoto = direction === 1
        ? activeProfileBookPhotos[targetIndex]
        : activeProfileBookPhotos[targetIndex + 1]
            || activeProfileBookPhotos[targetIndex];

    fillProfileBookFlipFace("Front", frontPhoto);
    fillProfileBookFlipFace("Back", backPhoto);

    profileBookSheet.className =
        "profile-book-flip-sheet";

    profileBookSheet.style.display = "block";

    profileBookSheet.classList.add(
        direction === 1 ? "flip-next" : "flip-prev"
    );

    // Allow browser to register the initial position
    void profileBookSheet.offsetWidth;

    requestAnimationFrame(() => {
        profileBookSheet.classList.add("is-flipping");
    });

    // Update the actual spread after the page-turn animation
    setTimeout(() => {

        activeProfileBookIndex = targetIndex;

        updateProfileBook();

        profileBookSheet.className =
            "profile-book-flip-sheet";

        profileBookSheet.style.display = "none";

        profileBookIsAnimating = false;

    }, 900);
}


