    // Use the existing shared gallery assets for the remaining pages.
    activeProfileBookPhotos = [
        memberPhoto,
        ...profileBookSharedPhotos.filter(
            photo => photo.src !== data.photo
        )
    ];

    activeProfileBookIndex = 0;
    profileBookIsAnimating = false;

    if (profileBookMember) {
        profileBookMember.textContent =
            `${data.name.toUpperCase()} — PHOTO COLLECTION`;
    }

    if (profileBookSheet) {
        profileBookSheet.className =
            "profile-book-flip-sheet";
        profileBookSheet.style.display = "none";
    }

    updateProfileBook();
}


