        clearInterval(lineTimer);
        clearInterval(bootTimer);
        modal.classList.remove("is-booting");
        modal.classList.add("is-video");

        video.controls = true;
        video.playsInline = true;
        if (videoMissing) videoMissing.hidden = true;
        showPlayButton("PLAY PRESENTATION");

        if (!ensureVideoSource()) {
            showVideoError();
            return;
        }

        video.load();
        setVideoStatus("READY TO PLAY");

        // The boot animation runs after the original click gesture. Autoplay may
        // therefore be blocked; the visible play button is the guaranteed fallback.
        const attempt = video.play();
        if (attempt && typeof attempt.then === "function") {
            attempt.then(() => {
                hidePlayButton();
                setVideoStatus("NOW PLAYING");
            }).catch(() => {
                showPlayButton("PLAY PRESENTATION");
                setVideoStatus("TAP TO PLAY");
            });
        }
    }

    function startBootSequence() {
        clearInterval(lineTimer);
        clearInterval(bootTimer);
        terminal.innerHTML = "";
        progress.style.width = "0%";
        percent.textContent = "0%";
        status.textContent = "INITIALIZING PRESENTATION";
        modal.classList.remove("is-video");
        modal.classList.add("is-booting");

        let lineIndex = 0;
        let value = 0;
        addTerminalLine("launching_quadra_tech_presentation.exe");

        lineTimer = setInterval(() => {
            if (lineIndex < bootLines.length) {
                addTerminalLine(bootLines[lineIndex]);
                lineIndex += 1;
            } else {
                clearInterval(lineTimer);
            }
        }, 470);

        bootTimer = setInterval(() => {
            value = Math.min(100, value + 5);
            progress.style.width = value + "%";
            percent.textContent = value + "%";
            if (value >= 100) {
                status.textContent = "PRESENTATION READY";
                clearInterval(bootTimer);
                setTimeout(() => {
                    if (modal.classList.contains("active")) showVideoStage();
                }, 650);
            }
        }, 230);
    }

    function openPresentation() {
        modal.classList.add("active");
        modal.classList.remove("is-opening", "is-booting", "is-video");
        modal.setAttribute("aria-hidden", "false");
        document.body.classList.add("presentation-screen-open");
        document.body.style.overflow = "hidden";
        video.pause();
        if (videoMissing) videoMissing.hidden = true;
        showPlayButton("PLAY PRESENTATION");

        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                modal.classList.add("is-opening");
                setTimeout(() => {
                    if (!modal.classList.contains("active")) return;
                    startBootSequence();
                }, 1550);
            });
        });
    }

    function closePresentation() {
        clearInterval(lineTimer);
        clearInterval(bootTimer);
        modal.classList.remove("active", "is-opening", "is-booting", "is-video");
        modal.setAttribute("aria-hidden", "true");
        document.body.classList.remove("presentation-screen-open");
        document.body.style.overflow = "";
        video.pause();
        try { video.currentTime = 0; } catch (error) {}
        showPlayButton("PLAY PRESENTATION");
    }

    async function playPresentation() {
        if (video.ended) {
            try { video.currentTime = 0; } catch (error) {}
        }
        if (!ensureVideoSource()) {
            showVideoError();
            return;
        }
        if (video.networkState === HTMLMediaElement.NETWORK_EMPTY) video.load();
        try {
            await video.play();
            hidePlayButton();
            if (videoMissing) videoMissing.hidden = true;
            setVideoStatus("NOW PLAYING");
        } catch (error) {
            showPlayButton("TAP TO PLAY");
            setVideoStatus(error && error.name === "NotAllowedError" ? "TAP TO PLAY" : "VIDEO NOT READY");
        }
    }

    launchButton.addEventListener("click", openPresentation);
    if (closeButton) closeButton.addEventListener("click", closePresentation);
    if (skipButton) {
        skipButton.addEventListener("click", () => {
            if (!modal.classList.contains("active")) return;
            modal.classList.add("is-opening");
            showVideoStage();
        });
    }
    if (playButton) playButton.addEventListener("click", playPresentation);

    modal.addEventListener("click", (event) => {
        if (event.target === modal) closePresentation();
    });
    document.addEventListener("keydown", (event) => {
        if (event.key === "Escape" && modal.classList.contains("active")) closePresentation();
    });

    video.addEventListener("loadedmetadata", () => {
        if (videoMissing) videoMissing.hidden = true;
        setVideoStatus("VIDEO READY");
        if (video.paused) showPlayButton("PLAY PRESENTATION");
    });
    video.addEventListener("loadeddata", () => {
        if (videoMissing) videoMissing.hidden = true;
        if (video.paused) showPlayButton("PLAY PRESENTATION");
    });
    video.addEventListener("play", () => {
        hidePlayButton();
        if (videoMissing) videoMissing.hidden = true;
        setVideoStatus("NOW PLAYING");
    });
    video.addEventListener("pause", () => {
        if (modal.classList.contains("is-video") && !video.ended && !video.error) {
            showPlayButton("RESUME PRESENTATION");
            setVideoStatus("PAUSED");
        }
    });
    video.addEventListener("ended", () => {
        showPlayButton("REPLAY PRESENTATION");
        setVideoStatus("PRESENTATION COMPLETE");
    });
    video.addEventListener("error", showVideoError);

    if (videoUpload) {
        videoUpload.addEventListener("change", () => {
            const file = videoUpload.files && videoUpload.files[0];
            if (!file) return;
            if (!file.type.startsWith("video/")) {
                showVideoError();
                setVideoStatus("PLEASE SELECT A VIDEO FILE");
                return;
            }
            if (currentObjectUrl) URL.revokeObjectURL(currentObjectUrl);
            currentObjectUrl = URL.createObjectURL(file);
            video.pause();
            video.removeAttribute("src");
            video.innerHTML = "";
            video.src = currentObjectUrl;
            video.load();
            if (videoMissing) videoMissing.hidden = true;
            showPlayButton("PLAY SELECTED VIDEO");
            setVideoStatus(file.name.toUpperCase());
        });
    }

    window.closeHackerPresentation = closePresentation;
})();
